                            c.getInventory().clearContent(); c.getInventory().add(new ItemStack(Items.IRON_PICKAXE)); c.getInventory().add(new ItemStack(Items.TORCH, 40)); c.getInventory().add(new ItemStack(Items.BREAD, 4));
                            c.setHealth(20); c.getFoodData().setFoodLevel(20); c.getFoodData().setSaturation(20f);
