            b.segments.add(new com.claudemod.entity.life.MineBlueprint.Segment(com.claudemod.entity.life.MineBlueprint.Kind.BRANCH, h.absolutePos(new BlockPos(10, 2, 15)), net.minecraft.core.Direction.NORTH, 7, null)); b.invalidate();
            for (var r : b.rows()) for (BlockPos f : r.feet()) for (int yy = 0; yy < r.height(); yy++) level.setBlock(f.above(yy), Blocks.AIR.defaultBlockState(), 2);
            for (int x = 9; x <= 11; x++) for (int z = 5; z <= 7; z++) for (int yy = 2; yy <= 4; yy++) level.setBlock(h.absolutePos(new BlockPos(x, yy, z)), Blocks.LAVA.defaultBlockState(), 2);
            BlockPos plug = h.absolutePos(new BlockPos(10, 2, 8)); level.setBlock(plug, Blocks.COBBLED_DEEPSLATE.defaultBlockState(), 2); level.setBlock(plug.above(), Blocks.COBBLED_DEEPSLATE.defaultBlockState(), 2);
