        if (t[0] == 135) { c.staying = false; routeStart = t[0]; ClaudeMod.LOGGER.info("[Claude test] stage 269 build_portal -> {}", com.claudemod.director.ClaudeLife.testSkill(c, mock[0], "build_portal", "", 1)); }
        if (routeStart > 0 && t[0] > routeStart) {
            oaFar = Math.max(oaFar, Math.sqrt(c.blockPosition().distSqr(oaStart)));
            check(oaFar <= 8, "269: off " + (int) oaFar + " blocks from the pool (last=" + c.lastSkillLine + ")");
            check(c.getHealth() >= 18 && !c.isOnFire(), "269: hurt (" + c.getHealth() + ") at " + c.blockPosition().toShortString() + " last=" + c.lastSkillLine);
            check(c.lastSkillLine == null || !c.lastSkillLine.contains("no way to the obsidian"), "269: " + c.lastSkillLine);
            check(com.claudemod.director.ClaudeLife.obsLost == 0, "269: " + com.claudemod.director.ClaudeLife.obsLost + " obsidian lost");
            int obs = c.getInventory().countItem(Items.OBSIDIAN);
            if (obs >= 2) pass(stage, t, obs + " obsidian from the one-deep pool: the near cell mined in place and picked up, the far cell next, never more than " + (int) oaFar + " off (" + (t[0] - routeStart) + " ticks)");
            else check(t[0] - routeStart < 1600, "269: " + obs + " obsidian after 80 s at " + c.blockPosition().toShortString() + " last=" + c.lastSkillLine + " now=" + c.currentTask + " tasks=" + c.tasks);
        }
