                            var sk = EntityType.SKELETON.create(level); BlockPos sp = h.absolutePos(new BlockPos(13, 2, 8));
                            sk.moveTo(sp.getX() + 0.5, sp.getY(), sp.getZ() + 0.5, 90, 0); sk.setItemSlot(net.minecraft.world.entity.EquipmentSlot.MAINHAND, new ItemStack(Items.BOW)); sk.setNoAi(true); sk.setPersistenceRequired(); level.addFreshEntity(sk); sk.setTarget(c); acSk = sk; // (no AI: it stands and shoots on the stage's clock, its rattle heard through the walls)
