                            for (int x = 1; x <= 3; x++) for (int z = 1; z <= 3; z++) for (int yy = 5; yy <= 6; yy++) h.setBlock(new BlockPos(x, yy, z), Blocks.STONE); // rock two thick over a corner: what underground reads as
