                            mock[0].teleportTo(at.getX() - 1.5, at.getY() + 20, at.getZ() + 0.5);
                            BlockPos f = c.blockPosition();
                            check(!com.claudemod.entity.goals.WorkGoal.underground(level, f), "underground: read under a tree's leaves in the open at " + f.toShortString());
                            check(com.claudemod.entity.goals.WorkGoal.underground(level, h.absolutePos(new BlockPos(2, 2, 2))), "underground: not read under two blocks of rock");
                            net.minecraft.world.entity.monster.Skeleton first = null;
                            for (int[] q : new int[][] {{14, 6}, {14, 10}}) { var sk = h.spawn(EntityType.SKELETON, new BlockPos(q[0], 2, q[1])); sk.setItemSlot(net.minecraft.world.entity.EquipmentSlot.MAINHAND, new ItemStack(Items.BOW)); sk.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD, new ItemStack(Items.IRON_HELMET)); sk.reassessWeaponGoal(); sk.setPersistenceRequired(); sk.setTarget(c); if (first == null) first = sk; }
