    /** Stages 224-226: the old nook beside the second stairs in the old layout (205's world): two chest rows, room over them, the bed in the middle row, his things in its chests; him on the level. */
    private static com.claudemod.entity.life.BaseNook oldNookSetup(ClaudeEntity c, GameTestHelper h, ServerLevel level, ServerPlayer[] mock) {
        for (int x = -6; x <= 30; x++) for (int z = -6; z <= 20; z++) { for (int yy = -3; yy <= 12; yy++) level.setBlock(h.absolutePos(new BlockPos(x, yy, z)), Blocks.STONE.defaultBlockState(), 2); level.setBlock(h.absolutePos(new BlockPos(x, 13, z)), Blocks.GRASS_BLOCK.defaultBlockState(), 2); }
        var E = net.minecraft.core.Direction.EAST;
        var b = new com.claudemod.entity.life.MineBlueprint(h.absolutePos(new BlockPos(0, 12, 8)), E, 2, 4);
        b.turn(net.minecraft.core.Direction.SOUTH);
        b.segments.add(new com.claudemod.entity.life.MineBlueprint.Segment(com.claudemod.entity.life.MineBlueprint.Kind.STAIRS, b.nextStart(true), net.minecraft.core.Direction.SOUTH, 4, null)); b.invalidate();
        b.segments.add(new com.claudemod.entity.life.MineBlueprint.Segment(com.claudemod.entity.life.MineBlueprint.Kind.FLAT, b.nextStart(true), net.minecraft.core.Direction.SOUTH, 6, null)); b.invalidate();
        for (var r : b.rows()) for (BlockPos f : r.feet()) for (int y = 0; y < r.height(); y++) level.setBlock(f.above(y), Blocks.AIR.defaultBlockState(), 2);
        c.blueprint = b; c.prefs.put("mine_model", "blueprint"); com.claudemod.director.ClaudeLife.bpSync(c);
        com.claudemod.entity.life.MineBlueprint.Row sr = null; for (var r : b.rows()) if (r.segment() == 2 && r.index() == 0) sr = r;
        BlockPos eastF = sr.feet()[0].getX() >= sr.feet()[sr.feet().length - 1].getX() ? sr.feet()[0] : sr.feet()[sr.feet().length - 1];
        var o = new com.claudemod.entity.life.BaseNook(eastF.east(), net.minecraft.core.Direction.SOUTH, net.minecraft.core.Direction.EAST).tunnelWidth(2);
        for (var e : o.cells().entrySet()) { BlockPos p = e.getKey(); var r = e.getValue();
            if (r == com.claudemod.entity.life.BaseNook.Role.WALK) level.setBlock(p, Blocks.AIR.defaultBlockState(), 2);
            else if (r == com.claudemod.entity.life.BaseNook.Role.CHEST) level.setBlock(p, Blocks.CHEST.defaultBlockState().setValue(net.minecraft.world.level.block.ChestBlock.FACING, o.chestFacing()), 2);
            else if (r == com.claudemod.entity.life.BaseNook.Role.TABLE) level.setBlock(p, Blocks.CRAFTING_TABLE.defaultBlockState(), 2);
            else if (r == com.claudemod.entity.life.BaseNook.Role.FURNACE) level.setBlock(p, Blocks.FURNACE.defaultBlockState(), 2); }
        for (BlockPos q : o.junkChestCells()) level.setBlock(q, Blocks.AIR.defaultBlockState(), 2);
        for (BlockPos q : new BlockPos[] {o.bedFoot(), o.bedHead()}) for (int y = 0; y <= 2; y++) level.setBlock(q.above(y), Blocks.STONE.defaultBlockState(), 2);
        BlockPos oFoot = o.cell(1, 2, 0), oHead = o.cell(2, 2, 0); for (int y = 1; y <= 2; y++) level.setBlock(oHead.above(y), Blocks.AIR.defaultBlockState(), 2);
        var bed = Blocks.RED_BED.defaultBlockState().setValue(net.minecraft.world.level.block.BedBlock.FACING, o.ahead);
        level.setBlock(oFoot, bed.setValue(net.minecraft.world.level.block.BedBlock.PART, net.minecraft.world.level.block.state.properties.BedPart.FOOT), 2);
        level.setBlock(oHead, bed.setValue(net.minecraft.world.level.block.BedBlock.PART, net.minecraft.world.level.block.state.properties.BedPart.HEAD), 2);
        if (level.getBlockEntity(o.chestCells().get(0)) instanceof net.minecraft.world.level.block.entity.ChestBlockEntity ch) { ch.setItem(0, new ItemStack(Items.DIAMOND, 7)); ch.setItem(1, new ItemStack(Items.RAW_IRON, 20)); ch.setItem(2, new ItemStack(Items.REDSTONE, 30)); }
        if (level.getBlockEntity(o.chestCells().get(2)) instanceof net.minecraft.world.level.block.entity.ChestBlockEntity ch) ch.setItem(0, new ItemStack(Items.COAL, 40));
        c.nook = o; for (BlockPos q : o.chestCells()) c.storageChests.add(q);
        for (var e : o.cells().entrySet()) c.landingCells.add(e.getKey());
        c.getInventory().clearContent(); c.getInventory().add(new ItemStack(Items.IRON_PICKAXE)); c.getInventory().add(new ItemStack(Items.COBBLESTONE, 64)); c.getInventory().add(new ItemStack(Items.COBBLESTONE, 64)); c.getInventory().add(new ItemStack(Items.OAK_PLANKS, 64)); c.getInventory().add(new ItemStack(Items.TORCH, 16)); c.getInventory().add(new ItemStack(Items.BREAD, 16));
        BlockPos me = b.rows().get(b.rows().size() - 2).first(); c.teleportTo(me.getX() + 0.5, me.getY(), me.getZ() + 0.5);
        BlockPos you = b.rows().get(b.rows().size() - 1).first(); if (mock[0] != null) mock[0].teleportTo(you.getX() + 0.5, you.getY(), you.getZ() + 0.5);
        c.setHealth(20); c.getFoodData().setFoodLevel(20); level.setDayTime(1000); c.tasks.clear(); c.attempts.clear(); c.dropCurrent = true;
        return o;
    }
