    /** His pack cleared, then the first four items worn (helmet, chest, legs, boots) and the rest carried; none: bare. */
    private static void rtGear(ClaudeEntity c, net.minecraft.world.item.Item... its) {
        c.getInventory().clearContent();
        var sl = new net.minecraft.world.entity.EquipmentSlot[] {net.minecraft.world.entity.EquipmentSlot.HEAD, net.minecraft.world.entity.EquipmentSlot.CHEST, net.minecraft.world.entity.EquipmentSlot.LEGS, net.minecraft.world.entity.EquipmentSlot.FEET};
        for (var s : sl) c.setItemSlot(s, ItemStack.EMPTY);
        for (int i = 0; i < its.length; i++) { if (i < 4 && its[i] instanceof net.minecraft.world.item.ArmorItem) c.setItemSlot(sl[i], new ItemStack(its[i])); else c.getInventory().add(new ItemStack(its[i])); }
    }
    /** A chat reply as the model returns it: the line, action none, replace, and the steps (skill, target, count triples). */
    private static com.google.gson.JsonObject rtReply(String text, Object... st) {
        var r = new com.google.gson.JsonObject(); r.addProperty("text", text); r.addProperty("action", "none"); r.addProperty("plan_change", "replace"); r.addProperty("new_goal", ""); r.add("standing", new com.google.gson.JsonArray());
        var a = new com.google.gson.JsonArray();
        for (int i = 0; i + 2 < st.length; i += 3) { var o = new com.google.gson.JsonObject(); o.addProperty("skill", (String) st[i]); o.addProperty("target", (String) st[i + 1]); o.addProperty("count", (Integer) st[i + 2]); o.addProperty("where", st[i].equals("give") ? "near_them" : "near_you"); a.add(o); }
        r.add("steps", a); return r;
    }
    private static com.google.gson.JsonArray prSteps(String... st) { var a = new com.google.gson.JsonArray(); for (int i = 0; i + 1 < st.length; i += 2) { var o = new com.google.gson.JsonObject(); o.addProperty("skill", st[i]); o.addProperty("target", st[i + 1]); o.addProperty("count", 1); o.addProperty("where", "near_you"); a.add(o); } return a; }
