                            String jr = com.claudemod.director.ClaudeLife.junkChestRoundNow(c, level);
                            BlockPos jAt = null; for (var tk : c.tasks) if (tk instanceof com.claudemod.entity.life.Task.Deposit dp) { jAt = dp.pos(); break; }
                            check(jAt != null && lnLow.junkChestCells().contains(jAt), "fetch: the junk round goes to " + jAt + " (" + jr + "), the lower nook's top row is " + lnLow.junkChestCells());
