                        if (t[0] == 1) { scenarioReset(c); com.claudemod.entity.life.Perception.reset(c); c.planning = false; c.nextPlanTick = c.tickCount + 20 * 600; c.lastStep = null; owMark = -1; for (var m : level.getEntitiesOfClass(net.minecraft.world.entity.Mob.class, c.getBoundingBox().inflate(80))) m.discard(); }
                        if (t[0] == 5) sleepTickets(h, level);
