                            for (int x = 3; x <= 14; x++) for (int z = 4; z <= 8; z++) for (int yy = 2; yy <= 3; yy++) level.setBlock(h.absolutePos(new BlockPos(x, yy, z)), Blocks.AIR.defaultBlockState(), 2); // a cave room under the rock
                            for (int z = 4; z <= 8; z++) { BlockPos q = h.absolutePos(new BlockPos(1, 2, z)); level.setBlock(q, Blocks.LAVA.defaultBlockState(), 2); owLava.add(q.immutable()); } // a pool behind the room's west wall
                            com.claudemod.director.ClaudeLife.lavaSeen(c).addFirst(h.absolutePos(new BlockPos(1, 2, 6)));
                            BlockPos me = h.absolutePos(new BlockPos(3, 2, 6)); c.teleportTo(me.getX() + 0.5, me.getY(), me.getZ() + 0.5); c.tasks.clear(); c.dropCurrent = true; c.getNavigation().stop();
                            BlockPos you = h.absolutePos(new BlockPos(13, 2, 6)); mock[0].teleportTo(you.getX() + 0.5, you.getY(), you.getZ() + 0.5); c.prefs.put("stay_close", "no");
                            c.getInventory().clearContent(); c.getInventory().add(new ItemStack(Items.WHITE_BED)); c.getInventory().add(new ItemStack(Items.COBBLESTONE, 32)); c.getInventory().add(new ItemStack(Items.TORCH, 8)); c.getInventory().add(new ItemStack(Items.BREAD, 8)); c.getInventory().add(new ItemStack(Items.IRON_PICKAXE));
