                            check(walled.isEmpty(), "sight: behind a stone wall and seen:" + walled);
                            for (int z = 4; z <= 13; z++) for (int y = 2; y <= 4; y++) level.setBlock(h.absolutePos(new BlockPos(6, y, z)), Blocks.AIR.defaultBlockState(), 3);
                            for (BlockPos b : new BlockPos[] {rail, web, torch, grav}) level.setBlock(b, Blocks.AIR.defaultBlockState(), 3);
