                                    BlockPos c0 = n297.cell(0, 3, 0), c1 = n297.cell(0, 3, 1); check(clog.stream().allMatch(q -> q.equals(c0) || q.equals(c1)), "pocket: the climb left blocks in the pocket off its column: " + clog); // (the climb's own 2 stay while he's up there: his way back down, taken down as he comes in)
                                    ClaudeMod.LOGGER.info("[Claude test] 297: up through the hole in {} ticks, left in the pocket {}", t[0] - m297, clog);
                                    c.setRoll(ClaudeEntity.Roll.WORK); c.tasks.add(new Task.GoTo(tunnel, 0.6)); p297 = 3; m297 = t[0];
