                            for (var pg : level.getEntitiesOfClass(net.minecraft.world.entity.monster.piglin.Piglin.class, c.getBoundingBox().inflate(16))) pg.discard();
                            c.staying = false; c.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD, ItemStack.EMPTY);
