                            c.getInventory().clearContent(); c.getInventory().add(new ItemStack(Items.DIAMOND_PICKAXE)); c.getInventory().add(new ItemStack(Items.WATER_BUCKET)); c.getInventory().add(new ItemStack(Items.BREAD, 4));
                            lwMark = -1; lwT = -1; lwPh = 0;
