                            boolean dry = lwT > 0 && lwPh == 0 && !level.getFluidState(ft).is(net.minecraft.tags.FluidTags.WATER) && !(c.currentTask instanceof Task.Pickup) && c.tasks.stream().noneMatch(x -> x instanceof Task.Pickup);
