                            if (c.inventory.count(x -> x.is(Items.OBSIDIAN)) >= 12) { lwMark = t[0]; pass(stage, t, "12 obsidian the user's way: the pocket at the lava's level " + (lwCell == null ? "-" : lwCell.toShortString()) + " (in at " + (lwT - 20) / 20 + " s), the top layer (" + top + " of 9) before one down (" + low + "), no plug, never hurt, in " + (t[0] - 20) / 20 + " s"); }
                            if (t[0] > 20 + 20 * 240) check(false, "technique: " + c.inventory.count(x -> x.is(Items.OBSIDIAN)) + " of 12 in 240 s (top " + top + ", low " + low + "): last " + c.lastSkillLine);
