            for (int k = -1; k <= 2; k++) { var z = EntityType.ZOMBIE.create(level); BlockPos zp = k == 2 ? me.north(5) : me.south(4).east(k); z.moveTo(zp.getX() + 0.5, zp.getY(), zp.getZ() + 0.5, 0, 0); z.setNoAi(true); level.addFreshEntity(z); zs.add(z); }
