            net.minecraft.world.phys.Vec3 a = new net.minecraft.world.phys.Vec3(me.getX(), me.getY(), me.getZ() - 100), b = new net.minecraft.world.phys.Vec3(me.getX(), me.getY(), me.getZ() + 100);
