            c.getInventory().clearContent(); c.getInventory().add(new ItemStack(Items.ENDER_EYE, 4)); c.getInventory().add(new ItemStack(Items.OBSIDIAN, 10)); c.getInventory().add(new ItemStack(Items.FLINT_AND_STEEL));
